function sliderSetup(min, max, defaultValue, step) {
    sliderS = createSlider(min, max, defaultValue, step);
    sliderS.position(180, 10);
    sliderV = createSlider(min, max, defaultValue, step);
    sliderV.position(180, 50);
}

function sliderValueInput() {
    var valueS = sliderS.value();
    var valueV = sliderV.value();
    var valueSet = [valueS, valueV];
    return valueSet;
}

