}

function draw() {
  if (trace == 0) {
    clear();
  }
  background(0);
  //mousePressed();
  //noStroke();
  //fill(20);
  //rect(0, 0, width, height);
  for (var i = 0; i < particles.length; i++) {
    for (var j = 0; j < attractors.length; j++) {
        var force = particles[i].attract(attractors[j]);
        particles[i].applyForce(force);
    }
    particles[i].update();
