function mouseClicked() {
  particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, 0));
  particles[particles.length - 1].createParticleImage();
}

function doubleClicked() {
  //particles = [];
  //attractors = [];
}

function keyTyped() {
  if (key === 'p') {
    particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, 0));
    particles[particles.length - 1].createParticleImage();
  }
  if (key === 'a') {
    attractors.push(new Attractor(width / 2, height / 2));
  }
  else if (key === 'r') {
    particles = [];
    attractors = [];
    clear();
    attractors.push(new Attractor(width / 2, height / 2));
  }
  else if (key === 'm') {
    for (var particle of particles) {
      particle.velocity.x = random(-5, 5);
      particle.velocity.y = random(-5, 5);
    }
  }
  else if (key === 'c') {
    if (trace == 0) {
      trace = 1;
    } else if (trace == 1) {
      trace = 0;
    }
  }
  else if (key === 's') {
    saveCanvas();
  }
}

